import { dbNodeToCrossApp as oldConv } from "./oldConv";
import { dbNodeToCrossApp as newConv } from "./newConv";

const spaceMap: Record<number, string> = {
  20: "obsidian:vault-a",
  21: "obsidian:vault-b",
  22: "https://roamresearch.com/#/app/g",
};
const accountMap: Record<number, string> = { 42: "acct-42" };
const schemaMap: Record<number, string> = {
  200: "orn:obsidian.schema:vault-a/evd-type",
  201: "https://roamresearch.com/#/app/g/clm-type",
};

const dims = {
  is_schema: [false, true, null],
  schema_id: [200, 201, null, 999],
  source_local_id: ["node-1", null, "https://roamresearch.com/#/app/g/uid"],
  space_id: [20, 22, null, 999],
  direct: ["ok", "undefined", "textNull"],
  created: ["2026-06-14T11:00:00", null, "garbage"],
  conceptLM: ["2026-06-14T12:00:00", null],
  directLM: ["2026-06-14T13:00:00", null],
  fullLM: ["2026-06-14T15:00:00", null],
  author_id: [42, null, 7],
  core_title: ["Core", null],
  formatMap: ["fmt", "empty", "none"],
  slots: ["none", "same", "cross", "dangling"],
} as const;

const keys = Object.keys(dims) as (keyof typeof dims)[];
let total = 0;
let diffs = 0;
const diffKinds = new Map<string, number>();
const outcomes = new Map<string, number>();

const run = (fn: typeof newConv, args: Parameters<typeof newConv>[0]) => {
  try {
    return { ok: JSON.stringify(fn(args)) };
  } catch (e) {
    return { err: (e as Error).message };
  }
};

const rec = (i: number, combo: Record<string, unknown>) => {
  if (i === keys.length) {
    total++;
    const c = combo as any;
    const slotDefs: Record<string, any> = {
      none: { rc: {}, cor: [] },
      same: { rc: { ev: 5 }, cor: [{ id: 5, space_id: c.space_id, source_local_id: "n5" }] },
      cross: { rc: { ev: 6 }, cor: [{ id: 6, space_id: 21, source_local_id: "n6" }] },
      dangling: { rc: { ev: 7, x: 8 }, cor: [{ id: 8, space_id: 999, source_local_id: "n8" }] },
    };
    const s = slotDefs[c.slots];
    const concept = {
      core_title: c.core_title,
      is_schema: c.is_schema,
      last_modified: c.conceptLM,
      schema_id: c.schema_id,
      source_local_id: c.source_local_id,
      space_id: c.space_id,
      reference_content: s.rc,
      concepts_of_relation: s.cor,
    };
    const direct =
      c.direct === "undefined"
        ? undefined
        : {
            author_id: c.author_id,
            created: c.created,
            last_modified: c.directLM,
            source_local_id: "node-1",
            space_id: 20,
            text: c.direct === "textNull" ? null : "EVD - Core",
            variant: "direct",
          };
    const formatMap: Record<number, string> =
      c.formatMap === "fmt" ? { 200: "EVD - {content}", 201: "CLM - {content}" } : c.formatMap === "empty" ? { 200: "", 201: "" } : {};
    const args = {
      row: { concept, direct, fullLastModified: c.fullLM },
      spaceMap,
      accountMap,
      schemaMap,
      formatMap,
    } as any;
    const a = run(oldConv, structuredClone(args));
    const b = run(newConv, structuredClone(args));
    const outKey = "ok" in b ? "ok" : `err:${b.err}`;
    outcomes.set(outKey, (outcomes.get(outKey) ?? 0) + 1);
    if (JSON.stringify(a) !== JSON.stringify(b)) {
      diffs++;
      const k = `${"ok" in a ? "ok" : "err:" + a.err} -> ${"ok" in b ? "ok" : "err:" + b.err}`;
      diffKinds.set(k, (diffKinds.get(k) ?? 0) + 1);
      if ((diffKinds.get(k) ?? 0) === 1) console.log("example", k, JSON.stringify(combo));
      if ("ok" in a && "ok" in b) console.log("OUTPUT DIFF", a.ok, b.ok);
    }
    return;
  }
  const k = keys[i]!;
  for (const v of dims[k]) rec(i + 1, { ...combo, [k]: v });
};
rec(0, {});
console.log({ total, diffs });
console.log("diff kinds:", Object.fromEntries(diffKinds));
console.log("new outcomes:", Object.fromEntries(outcomes));

